import base64,json,pathlib,shlex,subprocess,time
source="import json,pathlib,subprocess\nout={'containers':[],'homeDirs':[p.name for p in pathlib.Path('/home/ubuntu').iterdir() if p.is_dir()]}\nnames=subprocess.check_output(['docker','ps','--format','{{.Names}}'],text=True).splitlines()\nfor name in names:\n i=json.loads(subprocess.check_output(['docker','inspect',name],text=True))[0]\n out['containers'].append({'name':name,'workdir':i['Config']['WorkingDir'],'image':i['Image'],'mounts':[{'source':m['Source'],'dest':m['Destination'],'rw':m['RW']} for m in i['Mounts']],'safeEnv':[s for s in i['Config']['Env'] if s.split('=')[0] in ['DATA_DIR','LOG_DIR','GIT_SHA']]})\njs=r\"\"\"\nimport fs from 'node:fs';import path from 'node:path';import {config} from './src/config.ts';\nconst id='6814483810'; const out={dataDir:config.dataDir,logDir:config.logDir,dirs:[]};\nfor(const root of [config.dataDir,config.logDir]){\n if(!fs.existsSync(root)) continue;\n for(const de of fs.readdirSync(root,{withFileTypes:true})){\n  if(!de.isDirectory())continue;const p=path.join(root,de.name);\n  const row={root,slug:de.name,files:[]};\n  for(const f of fs.readdirSync(p)){\n   const fp=path.join(p,f),st=fs.statSync(fp);if(!st.isFile())continue;\n   if(f===id+'.json'){const c=JSON.parse(fs.readFileSync(fp,'utf8'));row.chat={epoch:c.epoch,history:c.history?.length,sent:c.sent?.length,ageConfirmed:c.ageConfirmed,who:c.who,modified:st.mtime.toISOString()};}\n   if(f.endsWith('.jsonl') && st.size<100000000){let matches=0,keys=[]; for(const l of fs.readFileSync(fp,'utf8').split('\\n'))if(l.includes(id)){matches++;if(!keys.length){try{keys=Object.keys(JSON.parse(l))}catch{}}}if(matches)row.files.push({f,bytes:st.size,matches,keys});}\n  }\n  if(row.chat||row.files.length)out.dirs.push(row);\n }\n}\nconsole.log(JSON.stringify(out));\n\"\"\";\np=subprocess.run(['docker','exec','-i','twin-v2-bot-1','node','--import','tsx','--input-type=module'],input=js,text=True,capture_output=True,timeout=45)\nassert p.returncode==0,p.stderr[-800:]\nout['v2']=json.loads(p.stdout)\nprint('RESET_PREFLIGHT '+json.dumps(out))\n"
command='python3 -c '+shlex.quote('import base64;exec(compile(base64.b64decode('+repr(base64.b64encode(source.encode()).decode())+'),"rcy07-preflight","exec"))')
p=pathlib.Path('/tmp/rcy07-ssm-params.json');p.write_text(json.dumps({'commands':[command],'executionTimeout':['120']}))
cid=subprocess.check_output(['aws','ssm','send-command','--instance-ids','i-0584d283506f3f6be','--document-name','AWS-RunShellScript','--parameters','file://'+str(p),'--comment','Read-only RCY07 reset preflight','--query','Command.CommandId','--output','text'],text=True).strip()
print('COMMAND '+cid,flush=True)
for _ in range(50):
 time.sleep(2)
 try:r=json.loads(subprocess.check_output(['aws','ssm','get-command-invocation','--command-id',cid,'--instance-id','i-0584d283506f3f6be','--output','json'],text=True,stderr=subprocess.DEVNULL))
 except subprocess.CalledProcessError:continue
 if r['Status'] in ['Success','Failed','Cancelled','TimedOut']:break
else:raise RuntimeError('SSM still running; inspect command '+cid)
print(r.get('StandardOutputContent',''),flush=True)
if r['Status']!='Success':raise RuntimeError(r.get('StandardErrorContent','')[-1500:])
